/* One hand-composed illustration per catalog service. Canvas 320 x 200. */
import type { ReactNode } from "react";
import {
  Badge, Bar, Bubble, C, Chart, Chip, Cloud, Code, Folder, G, Gear, Grid, Laptop, Lines, Monitor, Mountain, Mug, Paper, Person, Phone, Pie, Plant,
  Play, Printer, Tablet, TitleBar, Txt, Wave, Wifi,
} from "./kit";

type Scene = () => ReactNode;

const ring = (cx: number, cy: number, r: number, p: number, color: string) => {
  const c = 2 * Math.PI * r;
  return <g><circle cx={cx} cy={cy} r={r} fill="none" stroke={C.soft} strokeWidth={6} /><circle cx={cx} cy={cy} r={r} fill="none" stroke={color} strokeWidth={6} strokeLinecap="round" strokeDasharray={`${c * p} ${c}`} transform={`rotate(-90 ${cx} ${cy})`} /></g>;
};
const usb = (x: number, y: number) => <g><rect x={x} y={y} width={22} height={38} rx={4} fill={C.blue} /><rect x={x + 5} y={y - 10} width={12} height={12} rx={1} fill="#b9c3cc" /><rect x={x + 7} y={y - 7} width={3} height={3} fill={C.ink2} /><rect x={x + 12} y={y - 7} width={3} height={3} fill={C.ink2} /></g>;
const photoCard = (x: number, y: number, w: number, h: number, rot = 0) => <g transform={rot ? `rotate(${rot} ${x + w / 2} ${y + h / 2})` : undefined}><rect x={x} y={y} width={w} height={h} rx={3} fill={C.paper} stroke={C.line} /><Mountain x={x + 5} y={y + 5} w={w - 10} h={h - 16} /></g>;
const stamp = (cx: number, cy: number, color = C.rose) => <g><circle cx={cx} cy={cy} r={13} fill="none" stroke={color} strokeWidth={2.5} /><circle cx={cx} cy={cy} r={8} fill="none" stroke={color} strokeWidth={1.5} /></g>;
const docText = (x: number, y: number, w: number) => <><rect x={x} y={y} width={w * 0.6} height={5} rx={2.5} fill={C.ink2} /><Lines x={x} y={y + 13} w={w} n={4} gap={9} /></>;
const appIcons = (x: number, y: number, cols: number, rows: number, s = 14, gap = 6) => {
  const pal = [C.brown, C.green, C.blue, C.rose, C.gold, C.violet];
  const out: ReactNode[] = [];
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) out.push(<rect key={`${r}${c}`} x={x + c * (s + gap)} y={y + r * (s + gap)} width={s} height={s} rx={4} fill={pal[(r * cols + c) % pal.length]} />);
  return <g>{out}</g>;
};
const server = (x: number, y: number, n = 3) => <g>{Array.from({ length: n }, (_, i) => <g key={i}><rect x={x} y={y + i * 26} width={92} height={22} rx={4} fill={C.ink} /><circle cx={x + 10} cy={y + i * 26 + 11} r={3} fill={i === 1 ? C.gold : C.green} /><rect x={x + 22} y={y + i * 26 + 9} width={40} height={4} rx={2} fill={C.ink2} /><rect x={x + 70} y={y + i * 26 + 7} width={14} height={8} rx={2} fill={C.ink2} /></g>)}</g>;
const cardMock = (x: number, y: number, w: number, h: number, fill: string, rot = 0, children?: ReactNode) => <g transform={rot ? `rotate(${rot} ${x + w / 2} ${y + h / 2})` : undefined}><rect x={x + 2} y={y + 4} width={w} height={h} rx={6} fill="#000" opacity={0.1} /><rect x={x} y={y} width={w} height={h} rx={6} fill={fill} />{children}</g>;
const feedPost = (b: { w: number; h: number }) => <><rect x={6} y={6} width={b.w - 12} height={b.w - 12} rx={4} fill={C.brownL} /><circle cx={b.w / 2} cy={b.w / 2} r={b.w / 6} fill={C.brown} /><path d={`M${b.w / 2 - 6} ${b.w / 2} l4 4 l8 -9`} stroke="#fff" strokeWidth={2.5} fill="none" strokeLinecap="round" /><circle cx={12} cy={b.w + 2} r={4} fill={C.rose} /><Lines x={20} y={b.w} w={b.w - 30} n={2} gap={8} /></>;
const browser = (b: { w: number; h: number }, body: ReactNode) => <><TitleBar b={{ x: 0, y: 0, w: b.w, h: 12 }} /><rect x={34} y={3} width={b.w - 44} height={6} rx={3} fill={C.paper} />{body}</>;

